using ELedgerCare.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Xunit;

namespace ELedgerCare.Infrastructure.Tests;

/// <summary>
/// BIC-01: inspects the SQL actually generated by EF Core/Npgsql (no server needed) and the model mapping.
/// </summary>
public sealed class PersistenceMappingTests
{
    private static ELedgerCareDbContext CreateContext() => new(
        new DbContextOptionsBuilder<ELedgerCareDbContext>()
            .UseNpgsql("Host=127.0.0.1;Port=1;Database=sql_generation_only")
            .Options);

    [Fact]
    public void Metadata_projection_never_selects_original_bytes()
    {
        using var db = CreateContext();
        var key = Guid.NewGuid();

        var sql = IntakeStore.ProjectMetadata(db.Documents.Where(d => d.IdempotencyKey == key)).ToQueryString();

        Assert.Contains("byte_length", sql, StringComparison.Ordinal);
        Assert.Contains("sha256", sql, StringComparison.Ordinal);
        Assert.DoesNotContain(".bytes", sql, StringComparison.Ordinal);
        TestContext.Current.TestOutputHelper?.WriteLine(sql);
    }

    [Fact]
    public void Original_download_query_selects_only_bytes()
    {
        using var db = CreateContext();
        var id = Guid.NewGuid();

        var sql = db.OriginalArtifacts.Where(a => a.DocumentId == id).Select(a => a.Bytes).ToQueryString();

        Assert.Contains(".bytes", sql, StringComparison.Ordinal);
        Assert.DoesNotContain("sha256", sql, StringComparison.Ordinal);
    }

    [Fact]
    public void Artifact_and_job_foreign_keys_restrict_deletes()
    {
        using var db = CreateContext();
        var foreignKeys = db.Model.GetEntityTypes().SelectMany(e => e.GetForeignKeys()).ToList();

        Assert.Equal(2, foreignKeys.Count);
        Assert.All(foreignKeys, fk => Assert.Equal(DeleteBehavior.Restrict, fk.DeleteBehavior));
    }
}
